<?php
namespace App\Services;
use App\Models\Order;use App\Models\User;use Illuminate\Database\Eloquent\Builder;use Illuminate\Support\Facades\DB;
class CouponAudienceService { public function query(array $f):Builder{$q=User::query();if(!empty($f['user_ids']))$q->whereIn('id',array_map('intval',$f['user_ids']));if(!empty($f['emails']))$q->whereIn('email',array_map('strtolower',$f['emails']));if(!empty($f['plan_ids']))$q->whereIn('plan_id',array_map('intval',$f['plan_ids']));if(($f['subscription_status']??'')==='active')$q->where('expired_at','>',time());if(($f['subscription_status']??'')==='expired')$q->where('expired_at','<=',time());if(!empty($f['expires_after']))$q->where('expired_at','>=',(int)$f['expires_after']);if(!empty($f['expires_before']))$q->where('expired_at','<=',(int)$f['expires_before']);if(isset($f['auto_renewal'])&&$f['auto_renewal']!=='')$q->where('auto_renewal',(int)$f['auto_renewal']);if(!empty($f['registered_after']))$q->where('created_at','>=',(int)$f['registered_after']);if(!empty($f['registered_before']))$q->where('created_at','<=',(int)$f['registered_before']);if(!empty($f['remaining_traffic_min']))$q->whereRaw('(transfer_enable-u-d) >= ?',[(int)$f['remaining_traffic_min']*1073741824]);if(!empty($f['remaining_traffic_max']))$q->whereRaw('(transfer_enable-u-d) <= ?',[(int)$f['remaining_traffic_max']*1073741824]);if(!empty($f['never_purchased']))$q->whereNotIn('id',Order::where('status',3)->where('plan_id','>',0)->pluck('user_id'));if(!empty($f['inactive_since']))$q->whereNotIn('id',Order::where('status',3)->where('created_at','>=',(int)$f['inactive_since'])->pluck('user_id'));if(!empty($f['spent_min'])||!empty($f['spent_max'])){$spend=Order::where('status',3)->select('user_id',DB::raw('SUM(total_amount+COALESCE(balance_amount,0)) as spent'))->groupBy('user_id');if(!empty($f['spent_min']))$spend->having('spent','>=',(int)$f['spent_min']);if(!empty($f['spent_max']))$spend->having('spent','<=',(int)$f['spent_max']);$q->whereIn('id',$spend->pluck('user_id'));}return $q;} }
